.darma-loader-spinning-top {
  position: relative;
  width: 34px;
  height: 44px;
  transform-origin: bottom center;
  animation: darma-loader-spinning-top-wob 1.2s ease-in-out infinite;
}
.darma-loader-spinning-top::before {
  content: "";
  position: absolute;
  top: 8px;
  left: 50%;
  width: 30px;
  height: 32px;
  margin-left: -15px;
  background: var(--loader-color, #6366f1);
  clip-path: polygon(0 0, 100% 0, 50% 100%);
}
.darma-loader-spinning-top::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 50%;
  width: 30px;
  height: 11px;
  margin-left: -15px;
  border-radius: 50%;
  background: #4338ca;
}
@keyframes darma-loader-spinning-top-wob {
  0%, 100% { transform: rotate(-11deg); }
  50% { transform: rotate(11deg); }
}

